WITH filtered AS (SELECT *, CAST(txn_time AS DATE) AS txn_time_day, COALESCE(merchant, 'UNKNOWN') AS merchant_clean FROM transactions WHERE txn_time > DATE '2023-09-12' AND merchant IS NOT NULL AND amount >= 1300), metrics AS (SELECT *, AVG(amount) OVER (PARTITION BY merchant ORDER BY txn_time_day, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS amount_avg_6_prior, MAX(amount) OVER (PARTITION BY merchant ORDER BY CAST(txn_time AS BIGINT) RANGE BETWEEN 2592000 PRECEDING AND CURRENT ROW) AS amount_max_30d, LEAD(amount, 2) OVER (PARTITION BY txn_type ORDER BY txn_time, id) AS next_amount FROM filtered), joined AS (SELECT a.*, p2.opened_date FROM metrics a JOIN accounts p2 ON a.account_id = p2.id), with_windows AS (SELECT *, LEAD(amount, 2) OVER (PARTITION BY account_id ORDER BY txn_time_day, id) AS next_amount_2, NTILE(4) OVER (ORDER BY next_amount, id) AS next_amount_bucket, SUM(amount) OVER (PARTITION BY txn_type ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount, DENSE_RANK() OVER (ORDER BY amount_avg_6_prior DESC) AS amount_avg_6_prior_dense_rank FROM joined) SELECT DATE_TRUNC('MONTH', txn_time_day) AS activity_month, account_id, COUNT(DISTINCT txn_type) AS distinct_txn_types, APPROX_PERCENTILE(amount_avg_6_prior, ARRAY(0.25, 0.5, 0.75)) AS amount_avg_6_prior_quartiles, COUNT(*) FILTER (WHERE txn_type = 'FEE') AS fee_rows, PERCENTILE_APPROX(amount_avg_6_prior, 0.95) AS amount_avg_6_prior_p95, COUNT(*) AS cnt FROM with_windows GROUP BY activity_month, account_id HAVING distinct_txn_types < 1 ORDER BY distinct_txn_types NULLS FIRST
